// Yu Mincho Regular's GPOS "kern" pairs for kana (Version 1.92, 2048 units per em), read from Word's own copy of the face
// on the Windows box (lab/yumincho-kern). The Noto stand-in kerns other pairs (ー+サ, ー+ン, が+、 have none in Yu Mincho).
extension RichLayout {
    /// first << 16 | second -> adjustment in ems (negative closes up).
    static let yuMinchoKerns: [UInt32: Double] = {
        var t: [UInt32: Double] = [:]
        for e in yuMinchoKernData.split(separator: ",") {
            let p = e.split(separator: ":")
            guard p.count == 3, let a = UInt32(p[0], radix: 16), let b = UInt32(p[1], radix: 16), let v = Double(p[2]) else { continue }
            t[a << 16 | b] = v / 2048
        }
        return t
    }()
